//! The documentation must match the program: its command-line help, its MCP
//! tools and its configuration keys. Generated pages are compared with the
//! committed ones; refresh them with `REKKEFLY_BLESS=1 cargo test --test docs`.
use rekkefly::config::{Config, SourceConfig};
use serde_json::Value;
use std::{path::Path, process::Command};

fn root() -> &'static Path {
    Path::new(env!("CARGO_MANIFEST_DIR"))
}
fn read(relative: &str) -> String {
    std::fs::read_to_string(root().join(relative))
        .unwrap_or_default()
        .replace("\r\n", "\n")
}
/// Compare a generated file with the committed one, or write it when blessing.
fn check_generated(relative: &str, expected: &str) {
    if std::env::var_os("REKKEFLY_BLESS").is_some() {
        std::fs::write(root().join(relative), expected).unwrap();
        return;
    }
    assert!(
        read(relative) == expected,
        "{relative} is out of date. Regenerate it with: REKKEFLY_BLESS=1 cargo test --test docs"
    );
}
fn help(args: &[&str]) -> String {
    let output = Command::new(env!("CARGO_BIN_EXE_rekkefly"))
        .args(args)
        .output()
        .unwrap();
    assert!(output.status.success(), "rekkefly {args:?} failed");
    // Clap names the program after the executable: rekkefly.exe on Windows.
    String::from_utf8(output.stdout)
        .unwrap()
        .replace("\r\n", "\n")
        .replace("rekkefly.exe", "rekkefly")
}

#[test]
fn the_documented_help_is_the_programs() {
    let mut text = String::new();
    for args in [
        &["--help"][..],
        &["track", "--help"],
        &["clip", "--help"],
        &["mcp", "--help"],
    ] {
        if !text.is_empty() {
            text.push('\n');
        }
        text.push_str(&format!("$ rekkefly {}\n", args.join(" ")));
        text.push_str(help(args).trim_end());
        text.push('\n');
    }
    check_generated("book/src/reference/cli-help.txt", &text);
}

fn cell(text: &str) -> String {
    text.split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .replace('|', "\\|")
}
fn tool_reference(tools: &[Value]) -> String {
    let mut out = String::from(
        "# MCP tool schemas\n\n\
         <!-- Generated by tests/docs.rs from the server's tool list. Do not edit;\n     \
         run REKKEFLY_BLESS=1 cargo test --test docs instead. -->\n\n\
         Every tool `rekkefly mcp` offers, with its arguments, as the server reports\n\
         them in `tools/list`. Unknown arguments are rejected, and a tool that fails\n\
         returns `isError: true` with the reason. How to connect a client, and an\n\
         example session: [AI agents (MCP)](../guide/agents.md).\n\n\
         | Tool | What it does | Read-only |\n| --- | --- | --- |\n",
    );
    for tool in tools {
        let name = tool["name"].as_str().unwrap();
        let read_only = tool["annotations"]["readOnlyHint"].as_bool() == Some(true);
        out.push_str(&format!(
            "| [`{name}`](#{name}) | {} | {} |\n",
            cell(tool["title"].as_str().unwrap_or(name)),
            if read_only { "Yes" } else { "No" }
        ));
    }
    for tool in tools {
        let name = tool["name"].as_str().unwrap();
        out.push_str(&format!(
            "\n## {name}\n\n{}\n\n",
            tool["description"].as_str().unwrap().trim()
        ));
        let schema = &tool["inputSchema"];
        let properties = schema["properties"].as_object().unwrap();
        if properties.is_empty() {
            out.push_str("No arguments.\n");
            continue;
        }
        let required: Vec<&str> = schema["required"]
            .as_array()
            .map(|r| r.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        out.push_str("| Argument | Type | Required | Meaning |\n| --- | --- | --- | --- |\n");
        for (argument, spec) in properties {
            let mut kind = spec["type"].as_str().unwrap_or("any").to_owned();
            if let Some(values) = spec["enum"].as_array() {
                let values: Vec<String> = values.iter().map(|v| format!("`{v}`")).collect();
                kind = format!("{kind}: {}", values.join(", "));
            }
            if let Some(minimum) = spec.get("minimum") {
                kind = format!("{kind}, ≥ {minimum}");
            }
            out.push_str(&format!(
                "| `{argument}` | {} | {} | {} |\n",
                cell(&kind),
                if required.contains(&argument.as_str()) {
                    "Yes"
                } else {
                    ""
                },
                cell(spec["description"].as_str().unwrap_or(""))
            ));
        }
    }
    out
}

#[test]
fn every_mcp_tool_is_documented() {
    let tools = rekkefly::mcp::tools();
    let guide = read("docs/mcp.md");
    for tool in &tools {
        let name = tool["name"].as_str().unwrap();
        assert!(
            guide.contains(&format!("`{name}`")),
            "docs/mcp.md does not mention the tool {name}"
        );
    }
    check_generated("book/src/reference/mcp-tools.md", &tool_reference(&tools));
}

/// Dotted key paths of a serialized config; the four parts share one name.
fn keys(value: &toml::Value, prefix: &str, out: &mut Vec<String>) {
    if let toml::Value::Table(table) = value {
        for (key, value) in table {
            let path = if prefix.is_empty() {
                key.clone()
            } else {
                format!("{prefix}.{key}")
            };
            keys(value, &path, out);
        }
    } else {
        let mut path = prefix.to_owned();
        for part in ["left", "right", "head", "abdomen"] {
            path = path.replace(&format!("tracking.{part}."), "tracking.<part>.");
        }
        out.push(path);
    }
}

#[test]
fn every_config_key_is_documented() {
    let mut configs = vec![Config::default(), Config::demo()];
    for source in [
        SourceConfig::Video {
            path: "trial.avi".into(),
            width: 640,
            height: 480,
            fps: 30,
            repeat: false,
            realtime: true,
        },
        SourceConfig::Network {
            url: "rtsp://camera/fly".into(),
            width: 640,
            height: 480,
            fps: 30,
        },
    ] {
        configs.push(Config {
            source,
            ..Config::default()
        });
    }
    let reference = read("book/src/reference/configuration.md");
    let mut missing = Vec::new();
    for config in configs {
        let mut found = Vec::new();
        keys(&toml::Value::try_from(&config).unwrap(), "", &mut found);
        for key in found {
            if !reference.contains(&format!("`{key}`")) && !missing.contains(&key) {
                missing.push(key);
            }
        }
    }
    assert!(
        missing.is_empty(),
        "book/src/reference/configuration.md does not document: {missing:?}"
    );
}
